// EPICYCLE ATELIER
// Any closed curve is a stack of turning circles: take the curve's Fourier transform, sort the terms by size, and chain them,
// each circle riding on the rim of the one before. The end of the chain draws the curve. Few circles give a soft, rounded
// ghost of the figure; more circles sharpen it; the last few hundred give the corners back. The wobble knob detunes the
// machine so the drawing drifts, sways, or spins while it draws.
// Variables are re-read every frame; changing the figure re-takes the transform.

const CX = 400, CY = 400, SCALE = 330, M = 480;

const FIGURES = ['a heart', 'a five-pointed star', 'a trefoil knot', 'a butterfly', 'a hypotrochoid bloom', 'an infinity sign',
                 'a lightning bolt', 'a crescent moon', 'a five-petal rose', 'a cat\'s head'];

const COUNTS = { 'a handful': 5, 'half a dozen': 8, 'a dozen': 12, 'two dozen': 24, 'fifty': 50, 'a hundred': 100, 'a hundred and sixty': 160, 'every last circle': 300 };
const LOOPS_PER_SECOND = { 'glacial': 1 / 60, 'slow': 1 / 36, 'walking': 1 / 22, 'brisk': 1 / 14, 'fast': 1 / 8, 'frenzied': 1 / 4 };

const PALETTES = {
  'chalk on slate':  { bg: ['#2a3037', '#0d0f12'], trace: '#f4f1e8', ring: 'rgba(244,241,232,', accent: '#ffcf66' },
  'ink on vellum':   { bg: ['#f4ecd6', '#d8cba8'], trace: '#1a1612', ring: 'rgba(40,30,20,',    accent: '#b3392b' },
  'neon on black':   { bg: ['#090a12', '#000000'], trace: '#46f0d8', ring: 'rgba(70,240,216,',  accent: '#ff4fd8' },
  'blueprint':       { bg: ['#10357a', '#06183d'], trace: '#ffffff', ring: 'rgba(190,220,255,', accent: '#ffd36b' },
  'gold on oxblood': { bg: ['#4a1019', '#16040a'], trace: '#f0c869', ring: 'rgba(240,200,105,', accent: '#fff2c4' },
  'jade and cream':  { bg: ['#f1ead8', '#cfc5a8'], trace: '#0f6b57', ring: 'rgba(15,107,87,',   accent: '#d6563a' },
  'sunset duotone':  { bg: ['#2b1650', '#0e0720'], trace: '#ff8a5c', ring: 'rgba(255,138,92,',  accent: '#ffd6a5' },
  'ultraviolet':     { bg: ['#12062e', '#030010'], trace: '#b57bff', ring: 'rgba(181,123,255,', accent: '#ff7bd5' },
  'sodium lamp':     { bg: ['#1b1204', '#060401'], trace: '#ffb43b', ring: 'rgba(255,180,59,',  accent: '#ffe39a' },
  'seaglass':        { bg: ['#0c3a40', '#031316'], trace: '#9ff2d8', ring: 'rgba(159,242,216,', accent: '#ffffff' }
};

let figureKey = null, terms = [], contour = [];
let t = 0;
const TRAIL = 6000;
const tx = new Float32Array(TRAIL), ty = new Float32Array(TRAIL);
let head = 0, filled = 0;
let wander = [];

// ---- the figures ---------------------------------------------------------------------------------------------------
function raw(name) {
  const pts = [];
  const poly = (v) => { for (let i = 0; i < v.length; i++) { const a = v[i], b = v[(i + 1) % v.length]; for (let k = 0; k < 40; k++) pts.push([a[0] + (b[0] - a[0]) * k / 40, a[1] + (b[1] - a[1]) * k / 40]); } };
  if (name === 'a heart') for (let i = 0; i < 400; i++) { const a = i / 400 * 6.2832; pts.push([16 * Math.pow(Math.sin(a), 3), -(13 * Math.cos(a) - 5 * Math.cos(2 * a) - 2 * Math.cos(3 * a) - Math.cos(4 * a))]); }
  else if (name === 'a five-pointed star') { const v = []; for (let i = 0; i < 10; i++) { const r = i % 2 ? 0.42 : 1, a = -1.5708 + i * 0.6283; v.push([Math.cos(a) * r, Math.sin(a) * r]); } poly(v); }
  else if (name === 'a trefoil knot') for (let i = 0; i < 400; i++) { const a = i / 400 * 6.2832; pts.push([Math.sin(a) + 2 * Math.sin(2 * a), Math.cos(a) - 2 * Math.cos(2 * a)]); }
  else if (name === 'a butterfly') for (let i = 0; i < 1200; i++) { const a = i / 1200 * 37.699, r = Math.exp(Math.cos(a)) - 2 * Math.cos(4 * a) + Math.pow(Math.sin((2 * a - 3.1416) / 24), 5); pts.push([Math.sin(a) * r, -Math.cos(a) * r]); }
  else if (name === 'a hypotrochoid bloom') for (let i = 0; i < 800; i++) { const a = i / 800 * 6.2832 * 3, R = 5, r = 3, d = 5; pts.push([(R - r) * Math.cos(a) + d * Math.cos((R - r) / r * a), (R - r) * Math.sin(a) - d * Math.sin((R - r) / r * a)]); }
  else if (name === 'an infinity sign') for (let i = 0; i < 400; i++) { const a = i / 400 * 6.2832, d = 1 + Math.sin(a) * Math.sin(a); pts.push([Math.cos(a) / d, Math.sin(a) * Math.cos(a) / d]); }
  else if (name === 'a lightning bolt') poly([[0.15, -1], [-0.6, 0.05], [-0.08, 0.05], [-0.32, 1], [0.62, -0.12], [0.1, -0.12], [0.55, -1]]);
  else if (name === 'a crescent moon') { for (let i = 0; i <= 120; i++) { const a = (0.7 + i / 120 * 4.88); pts.push([Math.cos(a), Math.sin(a)]); } for (let i = 0; i <= 120; i++) { const a = (5.5 - i / 120 * 4.8); pts.push([0.42 + 0.78 * Math.cos(a) * 0.82, 0.78 * Math.sin(a)]); } }
  else if (name === 'a five-petal rose') for (let i = 0; i < 500; i++) { const a = i / 500 * 3.1416, r = Math.cos(5 * a); pts.push([r * Math.cos(a), r * Math.sin(a)]); }
  else poly([[-0.9, -0.95], [-0.5, -0.45], [0, -0.5], [0.5, -0.45], [0.9, -0.95], [0.95, 0], [0.6, 0.7], [0, 0.95], [-0.6, 0.7], [-0.95, 0]]);   // a cat's head
  return pts;
}

// resample to M points evenly along the curve, centre on the centroid, scale to fit
function prepare(name) {
  const pts = raw(name);
  const seg = [0];
  for (let i = 1; i <= pts.length; i++) { const a = pts[i - 1], b = pts[i % pts.length]; seg.push(seg[i - 1] + Math.hypot(b[0] - a[0], b[1] - a[1])); }
  const total = seg[seg.length - 1], out = [];
  let j = 0;
  for (let n = 0; n < M; n++) {
    const d = total * n / M;
    while (seg[j + 1] < d) j++;
    const a = pts[j], b = pts[(j + 1) % pts.length], f = (d - seg[j]) / Math.max(1e-9, seg[j + 1] - seg[j]);
    out.push([a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f]);
  }
  let mx = 0, my = 0;
  for (const q of out) { mx += q[0]; my += q[1]; }
  mx /= M; my /= M;
  let big = 0;
  for (const q of out) { q[0] -= mx; q[1] -= my; big = Math.max(big, Math.hypot(q[0], q[1])); }
  for (const q of out) { q[0] /= big; q[1] /= big; }
  return out;
}

// discrete Fourier transform, terms sorted by size (the mean sits at the centre and is dropped)
function transform(pts) {
  const res = [];
  for (let k = -M / 2; k < M / 2; k++) {
    if (k === 0) continue;
    let re = 0, im = 0;
    for (let n = 0; n < M; n++) {
      const a = -6.2832 * k * n / M, c = Math.cos(a), s = Math.sin(a);
      re += pts[n][0] * c - pts[n][1] * s; im += pts[n][0] * s + pts[n][1] * c;
    }
    re /= M; im /= M;
    res.push({ k: k, amp: Math.hypot(re, im), ph: Math.atan2(im, re) });
  }
  res.sort((a, b) => b.amp - a.amp);
  return res;
}

p.setup = function () {
  p.createCanvas(800, 800);
  p.pixelDensity(1);
  p.frameRate(60);
};

function rgba(base, a) { return base + a + ')'; }

p.draw = function () {
  const fig = p.getSynthVar('figure') || 'a heart';
  const circles = p.getSynthVar('circles') || 'two dozen';
  const machinery = p.getSynthVar('machinery') || 'bare circles';
  const trace = p.getSynthVar('trace') || 'thin wire';
  const palName = p.getSynthVar('palette') || 'chalk on slate';
  const speed = p.getSynthVar('speed') || 'walking';
  const wobble = p.getSynthVar('wobble') || 'steady';

  if (fig !== figureKey) {
    contour = prepare(FIGURES.indexOf(fig) >= 0 ? fig : 'a heart');
    terms = transform(contour); figureKey = fig;
    head = 0; filled = 0; wander = terms.map(() => 0);
  }
  const N = Math.min(COUNTS[circles] || 24, terms.length);
  const pal = PALETTES[palName] || PALETTES['chalk on slate'];
  const lps = LOOPS_PER_SECOND[speed] || 1 / 22;
  const SUB = lps < 1 / 30 ? 1 : lps < 1 / 12 ? 2 : 3;      // trace points per frame: fewer when slow, so a whole loop fits the buffer

  // advance the clock and lay down trace points
  let cur = null;
  for (let s = 0; s < SUB; s++) {
    t += lps / 60 / SUB;
    const sec = p.frameCount / 60;
    let x = 0, y = 0;
    const joints = [];
    for (let i = 0; i < N; i++) {
      const tm = terms[i];
      let amp = tm.amp, ph = tm.ph, fk = tm.k;
      if (wobble === 'a gentle sway') ph += 0.35 * Math.sin(sec * 0.4 + i * 1.3);
      else if (wobble === 'drunk') { wander[i] += (Math.random() - 0.5) * 0.03; wander[i] *= 0.998; ph += wander[i] * 3; }
      else if (wobble === 'breathing') amp *= 1 + 0.16 * Math.sin(sec * 0.8 + i * 0.9);
      else if (wobble === 'detuned') fk = tm.k * (1 + 0.0035);
      const a = 6.2832 * fk * t + ph + (wobble === 'a slow spin' ? sec * 0.12 : 0);
      x += amp * Math.cos(a); y += amp * Math.sin(a);
      joints.push([x, y, amp]);
    }
    cur = joints;
    tx[head] = CX + x * SCALE; ty[head] = CY + y * SCALE;
    head = (head + 1) % TRAIL; filled = Math.min(TRAIL, filled + 1);
  }

  // ---- paint ----
  const ctx = p.drawingContext;
  const g = ctx.createRadialGradient(CX, CY, 40, CX, CY, 620);
  g.addColorStop(0, pal.bg[0]); g.addColorStop(1, pal.bg[1]);
  ctx.setLineDash([]); ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  ctx.fillStyle = g; ctx.fillRect(0, 0, 800, 800);

  if (trace === 'beside its ideal') {
    ctx.strokeStyle = rgba(pal.ring, 0.28); ctx.lineWidth = 1.2; ctx.beginPath();
    for (let i = 0; i <= M; i++) { const q = contour[i % M]; if (i === 0) ctx.moveTo(CX + q[0] * SCALE, CY + q[1] * SCALE); else ctx.lineTo(CX + q[0] * SCALE, CY + q[1] * SCALE); }
    ctx.stroke();
  }

  // the machinery
  if (machinery !== 'invisible machinery' && cur) {
    let px = 0, py = 0;
    for (let i = 0; i < cur.length; i++) {
      const jx = CX + cur[i][0] * SCALE, jy = CY + cur[i][1] * SCALE, r = cur[i][2] * SCALE;
      if (machinery === 'bare circles') {
        ctx.strokeStyle = rgba(pal.ring, 0.6); ctx.lineWidth = 1.2; ctx.beginPath();
        ctx.arc(CX + px, CY + py, r, 0, 6.2832); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(CX + px, CY + py); ctx.lineTo(jx, jy); ctx.stroke();
      } else if (machinery === 'ghost circles') {
        ctx.strokeStyle = rgba(pal.ring, 0.16); ctx.lineWidth = 1; ctx.beginPath(); ctx.arc(CX + px, CY + py, r, 0, 6.2832); ctx.stroke();
      } else if (machinery === 'spokes only') {
        ctx.strokeStyle = rgba(pal.ring, 0.55); ctx.lineWidth = 1.2; ctx.beginPath(); ctx.moveTo(CX + px, CY + py); ctx.lineTo(jx, jy); ctx.stroke();
      } else if (machinery === 'pearls on spokes') {
        ctx.strokeStyle = rgba(pal.ring, 0.35); ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(CX + px, CY + py); ctx.lineTo(jx, jy); ctx.stroke();
        ctx.fillStyle = pal.accent; ctx.beginPath(); ctx.arc(jx, jy, Math.max(1.6, Math.min(5, r * 0.12)), 0, 6.2832); ctx.fill();
      } else if (machinery === 'gear teeth') {
        ctx.strokeStyle = rgba(pal.ring, 0.55); ctx.lineWidth = Math.max(1.5, Math.min(6, r * 0.12));
        ctx.setLineDash([2, Math.max(2, Math.min(9, r * 0.25))]); ctx.beginPath(); ctx.arc(CX + px, CY + py, r, 0, 6.2832); ctx.stroke(); ctx.setLineDash([]);
      } else if (machinery === 'glass discs') {
        ctx.fillStyle = rgba(pal.ring, 0.06); ctx.strokeStyle = rgba(pal.ring, 0.25); ctx.lineWidth = 1;
        ctx.beginPath(); ctx.arc(CX + px, CY + py, r, 0, 6.2832); ctx.fill(); ctx.stroke();
      }
      px = cur[i][0] * SCALE; py = cur[i][1] * SCALE;
    }
  }

  // the trace
  const loop = Math.round(60 * SUB / lps);                                          // trace points in one full loop
  const want = trace === 'comet' ? Math.round(loop * 0.12) : trace === 'ribbon' ? Math.round(loop * 0.5)
             : trace === 'neon glow' ? Math.round(loop * 0.7) : Math.round(loop * 1.02);
  const L = Math.min(filled, want, TRAIL - 1);
  const at = (n) => { const idx = (head - 1 - n + TRAIL * 2) % TRAIL; return [tx[idx], ty[idx]]; };
  ctx.setLineDash([]);
  if (L > 2) {
    if (trace === 'dotted') {
      ctx.fillStyle = pal.trace;
      ctx.beginPath();
      for (let n = 0; n < L; n += 5) { const q = at(n); ctx.moveTo(q[0] + 2, q[1]); ctx.arc(q[0], q[1], 2, 0, 6.2832); }
      ctx.fill();
    } else if (trace === 'comet' || trace === 'ribbon') {
      const w = trace === 'comet' ? 4.2 : 7.5, step = Math.max(1, Math.floor(L / 60));
      for (let n = 0; n + step < L; n += step) {
        const a = at(n), b = at(n + step), f = 1 - n / L;
        ctx.strokeStyle = pal.trace; ctx.globalAlpha = Math.max(0.03, f * f); ctx.lineWidth = Math.max(0.8, w * f);
        ctx.beginPath(); ctx.moveTo(a[0], a[1]); ctx.lineTo(b[0], b[1]); ctx.stroke();
      }
      ctx.globalAlpha = 1;
    } else {
      const passes = trace === 'neon glow' ? [[10, 0.12], [4.5, 0.28], [2.2, 0.95]] : [[2.2, 0.95]];
      for (const ps of passes) {
        ctx.strokeStyle = pal.trace; ctx.lineWidth = ps[0]; ctx.globalAlpha = ps[1]; ctx.beginPath();
        for (let n = 0; n < L; n++) { const q = at(n); if (n === 0) ctx.moveTo(q[0], q[1]); else ctx.lineTo(q[0], q[1]); }
        ctx.stroke();
      }
      ctx.globalAlpha = 1;
    }
    const h = at(0);
    ctx.fillStyle = pal.accent; ctx.beginPath(); ctx.arc(h[0], h[1], 5.5, 0, 6.2832); ctx.fill();
  }
  ctx.lineCap = 'butt';
};
